//! The standard proof plans (`Kernel.Std`, `tools/proof-kernel/lib/std.av`),
//! compiled to Rust and embedded, so a law with `by Kernel.Std.<plan>` runs
//! its plan in process: no compilation of the plan's Aver source and no VM.
//! `aver_generated/` and `runtime_support.rs` are generated by
//! `tools/regenerate_proof_kernel.py` and must not be edited by hand; this
//! file is the only interface.
//!
//! Nothing here is trusted. This tree is separate from `proof_kernel` on
//! purpose: a plan only writes proof steps, which the compiler reads back
//! and the kernel checks like any other proof.
#![allow(
    clippy::all,
    unused_variables,
    unused_mut,
    dead_code,
    unused_imports,
    unused_parens,
    unused_braces,
    non_snake_case,
    non_camel_case_types,
    unreachable_patterns,
    hidden_glob_reexports
)]

pub use ::aver_rt::AverMap as HashMap;
pub use ::aver_rt::AverStr;
pub use ::aver_rt::Buffer;
pub use ::aver_rt::ByteBuilder;

mod runtime_support;
pub use runtime_support::*;

pub mod aver_generated;

/// Run the standard plan `plan` on a goal in step data
/// (`crate::ir::proof_steps::sexpr`, wrapped as `(goal (elems …) SCRIPT)`).
/// The answer is what a project plan's runner returns: `proof` and the
/// proof on the next line, `refused` and the reason, or `goal` and why the
/// goal could not be read.
pub fn run(plan: &str, goal: &str) -> Result<String, String> {
    std::panic::catch_unwind(|| {
        aver_generated::entry::run(AverStr::from(plan), AverStr::from(goal)).to_string()
    })
    .map_err(|_| format!("the standard plan {plan} stopped with an internal error"))
}

/// Run a plan's script (`Kernel.Std.Tactic` in step data, as
/// `Kernel.Std.scriptAnswer` writes it) once on a goal written as for
/// [`run`], with the compiler's answers so far
/// (`(answers (a "KEY" REPLY)…)`). The answer is `proof` and the proof,
/// `refused` and the reason, `ask` and the question the script needs
/// answered next (an Auto or Plan node), or `goal` and why the input could
/// not be read.
pub fn run_script(goal: &str, script: &str, answers: &str) -> Result<String, String> {
    std::panic::catch_unwind(|| {
        aver_generated::entry::script(
            AverStr::from(goal),
            AverStr::from(script),
            AverStr::from(answers),
        )
        .to_string()
    })
    .map_err(|_| "the standard script runner stopped with an internal error".to_string())
}
